import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const scythePhysicalScenarios=['scythe-physical-ordinary','scythe-physical-dedicated','scythe-physical-ordinary-low','scythe-physical-dedicated-low'] as const;
export type ScythePhysicalScenario=typeof scythePhysicalScenarios[number];
export function isScythePhysicalScenario(name:string):name is ScythePhysicalScenario{return scythePhysicalScenarios.some(x=>x===name);}
export const SCYTHE='a2-p09-r3c1';
export function makeScythePhysicalScenario(name:ScythePhysicalScenario,players:{id:string;name:string}[],options:{level?:number;foreign?:boolean;follower?:'none'|'guardian'|'metal'}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[options.foreign?'魔導王ガイナス':'不死王ガドューラ','侍大将のシン','大神官ジル','白魔術師シェリム'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+(name.endsWith('-low')&&[b,c].includes(p.id)?0:6)-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.warrior_level=20+(options.level??7)-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,SCYTHE),takeCard(s,b,'a2-p06-r1c1'),takeCard(s,b,'a2-p05-r3c1'),takeCard(s,d,'命運凶変')];const guard=options.follower==='none'?null:takeCard(s,b,options.follower==='guardian'?'守護者':'メタルゴーレム'),soldier=options.follower==='none'?null:takeCard(s,c,'兵士');keep.push(...[guard,soldier].filter((x):x is string=>!!x));if(options.follower==='guardian')keep.push(takeCard(s,a,'必勝の祈り'));for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`SCYTHE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('SCYTHE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('SCYTHE_IDS');}
 for(const p of players){if(p.id===b&&guard)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});if(p.id===c&&soldier)act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:soldier});act(p.id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
